"""ROADMAP.md and changelog drafts, generated from the milestone of the issues.

The milestone key of the issues is the only source of the roadmap (tooling-root
ADR 0003). The format is specified in dev/spec/roadmap.md.
"""

import re
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

from r2.core import issues
from r2.core.issues import Issue

FILE = "ROADMAP.md"

ROADMAP_HEADER = """\
# Roadmap

<!-- Generated by `r2 roadmap` from the milestones of the open issues in
dev/issues. Do not edit by hand: change the milestone of an issue instead. -->

Open issues grouped by milestone, in version order. Issues without a milestone
are left out.
"""
NO_MILESTONES = "No open issue has a milestone.\n"

# Keep a Changelog headings for each kind, in the order they are printed.
# Tasks and issues without a kind fall in OTHER.
SECTIONS = {"enhancement": "Added", "defect": "Fixed"}
OTHER = "Other"
DONE = "completed"


@dataclass(frozen=True)
class Section:
    """A heading of a changelog draft and the issues under it, by slug."""

    title: str
    issues: list[tuple[str, Issue]]


def load(folder: Path) -> dict[str, Issue]:
    """Every issue in folder, by slug, in slug order."""
    return {path.stem: issues.load(path) for path in sorted(folder.glob("*.md"))}


def milestone(issue: Issue) -> str | None:
    """The milestone of the issue as text, or None without one."""
    value = issue.meta.get("milestone")
    text = "" if value is None else str(value).strip()
    return text or None


def milestone_key(name: str) -> tuple[tuple[str | int, ...], str]:
    """Sort key that orders milestone names as versions.

    Runs of digits compare as numbers, so 0.10.0 follows 0.9.0 and M10
    follows M9. The rest compares without case.
    """
    parts = re.split(r"(\d+)", name.casefold())
    # split alternates text and digits, so equal positions hold equal types.
    key = tuple(int(part) if index % 2 else part for index, part in enumerate(parts))
    return key, name


def milestones(found: Mapping[str, Issue]) -> list[str]:
    """Every milestone used by the issues, open or closed, in version order."""
    names = {name for issue in found.values() if (name := milestone(issue))}
    return sorted(names, key=milestone_key)


def open_by_milestone(found: Mapping[str, Issue]) -> dict[str, list[tuple[str, Issue]]]:
    """The open issues with a milestone, grouped by it, in version order."""
    groups: dict[str, list[tuple[str, Issue]]] = {}
    for slug, issue in sorted(found.items()):
        if issue.is_open and (name := milestone(issue)):
            groups.setdefault(name, []).append((slug, issue))
    return {name: groups[name] for name in sorted(groups, key=milestone_key)}


def render_roadmap(found: Mapping[str, Issue]) -> str:
    """The text of ROADMAP.md for the issues, by slug."""
    groups = open_by_milestone(found)
    parts = [ROADMAP_HEADER]
    if not groups:
        parts.append(NO_MILESTONES)
    for name, items in groups.items():
        lines = [f"## {name}", ""]
        lines += [f"- [{_escape(issue.title)}]({_link(slug)})" for slug, issue in items]
        parts.append("\n".join(lines) + "\n")
    return "\n".join(parts)


def changelog_sections(found: Mapping[str, Issue], name: str) -> list[Section]:
    """The completed issues of milestone name, grouped by kind.

    Empty sections are left out.
    """
    titles = [*SECTIONS.values(), OTHER]
    grouped: dict[str, list[tuple[str, Issue]]] = {title: [] for title in titles}
    for slug, issue in sorted(found.items()):
        if issue.status == DONE and milestone(issue) == name:
            kind = str(issue.meta.get("kind") or "")
            grouped[SECTIONS.get(kind, OTHER)].append((slug, issue))
    return [Section(title, items) for title, items in grouped.items() if items]


def render_changelog(name: str, sections: list[Section]) -> str:
    """A changelog draft in the Keep a Changelog layout, without a date."""
    lines = [f"## [{name}]"]
    for section in sections:
        lines += ["", f"### {section.title}", ""]
        lines += [f"- {issue.title} (`{slug}`)" for slug, issue in section.issues]
    return "\n".join(lines) + "\n"


def _link(slug: str) -> str:
    return f"{issues.FOLDER}/{slug}.md"


def _escape(title: str) -> str:
    """Escape what would end the text of a Markdown link early."""
    return re.sub(r"([\\\[\]])", r"\\\1", title)
